insert into public.posts (slug,title,category,excerpt,cover_image,cover_alt,seo_description,body,read_minutes,status,published_at) values
  ($lot$10-restaurants-locals-actually-go-to$lot$,$lot$10 Restaurants Locals Actually Go To$lot$,$lot$local$lot$,$lot$Skip the tourist traps. Here's where the regulars actually eat in Old Town.$lot$,$lot$../assets/home-luxury.jpg$lot$,$lot$10 Restaurants Locals Actually Go To$lot$,$lot$Skip the tourist traps. Here's where the regulars actually eat in Old Town.$lot$,$lot$<p>The local favorites that aren't on every visitor's list — no chains, just the Old Town spots the regulars keep going back to.</p>$lot$,2,'published', now() - interval '0 minutes'),
  ($lot$best-rooftop-condos-old-town-scottsdale$lot$,$lot$Best Rooftop Condos in Old Town$lot$,$lot$neighborhood$lot$,$lot$From private terraces to shared sky decks — the buildings with the best elevated living in Old Town.$lot$,$lot$../assets/blog-rooftop.jpg$lot$,$lot$Best Rooftop Condos in Old Town$lot$,$lot$From private terraces to shared sky decks — the buildings with the best elevated living in Old Town.$lot$,$lot$<p>Old Town's best rooftop living ranges from private terraces to shared sky decks with skyline and mountain views. Here's how the standout buildings compare on views, amenities, and walkability.</p>$lot$,2,'published', now() - interval '1 minutes'),
  ($lot$can-you-airbnb-in-old-town-scottsdale$lot$,$lot$Can You Airbnb in Old Town Scottsdale?$lot$,$lot$str$lot$,$lot$Zoning rules, permit requirements, and where short-term rentals actually make sense in Old Town.$lot$,$lot$../assets/blog-house.jpg$lot$,$lot$Can You Airbnb in Old Town Scottsdale?$lot$,$lot$Zoning rules, permit requirements, and where short-term rentals actually make sense in Old Town.$lot$,$lot$<p>Short-term rentals are legal in Scottsdale, but the details decide everything — City permitting, STR-specific insurance, and the HOA CC&amp;Rs that govern whether a specific building or home can rent under 30 days. Out here, most short-term rentals are single-family homes for exactly that reason.</p>$lot$,2,'published', now() - interval '2 minutes'),
  ($lot$fred-woodworth$lot$,$lot$Fred Woodworth: Old Town's Quiet, Consequential Builder$lot$,$lot$builders$lot$,$lot$Woodworth's neighborhoods are some of the most intact pockets of original Old Town — and patient buyers wait years for one.$lot$,$lot$../assets/fred-woodworth.jpg$lot$,$lot$Fred Woodworth: Old Town&#x27;s Quiet, Consequential Builder$lot$,$lot$Woodworth's neighborhoods are some of the most intact pockets of original Old Town — and patient buyers wait years for one.$lot$,$lot$<p>Fred Woodworth is quiet but consequential. His neighborhoods are among the most intact pockets of original Old Town today, and patient buyers routinely wait years for the right one to come to market.</p><p>If you're drawn to authenticity — original character, mature streets, and a strong sense of place — a Woodworth pocket is worth knowing by name before you start touring.</p>$lot$,2,'published', now() - interval '3 minutes'),
  ($lot$hallcraft-homes$lot$,$lot$Why Hallcraft Homes Shaped Old Town$lot$,$lot$builders$lot$,$lot$The volume builder behind most of Old Town's original single-family stock — and what to look for when you buy or renovate one.$lot$,$lot$../assets/hallcraft-homes.jpg$lot$,$lot$Why Hallcraft Homes Shaped Old Town$lot$,$lot$The volume builder behind most of Old Town's original single-family stock — and what to look for when you buy or renovate one.$lot$,$lot$<p>Hallcraft Homes is the name behind a huge share of Old Town Scottsdale's original single-family housing. Compact, well-sited, and full of period details, these postwar homes from the 1950s and '60s formed the backbone of the neighborhoods locals still fight to buy into today.</p><p>Knowing you're looking at a Hallcraft matters. The floor plans, lot placement, and construction are consistent enough that experienced buyers recognize them on sight — and value the details worth preserving in a renovation.</p>$lot$,2,'published', now() - interval '4 minutes'),
  ($lot$optima$lot$,$lot$Optima: The High-Rise That Redefined the Scottsdale Condo$lot$,$lot$builders$lot$,$lot$Vertical gardens, full amenity stacks, and the most-traded address in Old Town's luxury condo market.$lot$,$lot$../assets/optima-camelview.jpg$lot$,$lot$Optima: The High-Rise That Redefined the Scottsdale Condo$lot$,$lot$Vertical gardens, full amenity stacks, and the most-traded address in Old Town's luxury condo market.$lot$,$lot$<p>Optima redefined what a Scottsdale condo could be: vertical gardens, full amenity stacks, and architecture that reads as unmistakably modern. It's become one of the most-traded luxury addresses in Old Town.</p><p>For buyers weighing the lock-and-leave lifestyle, Optima is the flagship reference point — and a useful benchmark for comparing every other building in the market.</p>$lot$,2,'published', now() - interval '5 minutes'),
  ($lot$ralph-haver$lot$,$lot$Ralph Haver: Phoenix's Mid-Century Architect in Old Town$lot$,$lot$builders$lot$,$lot$Clean lines, low pitches, courtyard-forward plans — the Haver homes that became cult objects.$lot$,$lot$../assets/ralph-haver.jpg$lot$,$lot$Ralph Haver: Phoenix&#x27;s Mid-Century Architect in Old Town$lot$,$lot$Clean lines, low pitches, courtyard-forward plans — the Haver homes that became cult objects.$lot$,$lot$<p>Ralph Haver is Phoenix's defining mid-century architect, and his homes in and around Old Town are cult objects today. Clean rooflines, low pitches, and courtyard-forward floor plans give them a timeless, light-filled feel that modern buyers chase.</p><p>Because they're recognizable and increasingly rare, well-kept Haver homes command a premium — and reward owners who renovate with a light, period-respecting touch.</p>$lot$,2,'published', now() - interval '6 minutes'),
  ($lot$spring-2026-market-report$lot$,$lot$Spring 2026 Market Report$lot$,$lot$market$lot$,$lot$Pricing trends, inventory shifts, and what buyers and sellers should expect this season in Old Town.$lot$,$lot$../assets/home-pool.jpg$lot$,$lot$Spring 2026 Market Report$lot$,$lot$Pricing trends, inventory shifts, and what buyers and sellers should expect this season in Old Town.$lot$,$lot$<p>A season-by-season read on the Old Town Scottsdale market — what's happening with pricing, inventory, and buyer demand, and what it means if you're planning to buy or sell.</p>$lot$,2,'published', now() - interval '7 minutes'),
  ($lot$tw-lewis$lot$,$lot$T.W. Lewis: Larger Custom Homes That Aged Well$lot$,$lot$builders$lot$,$lot$The late-era builder behind some of Old Town's larger custom homes — solid construction, generous lots.$lot$,$lot$../assets/tw-lewis.png$lot$,$lot$T.W. Lewis: Larger Custom Homes That Aged Well$lot$,$lot$The late-era builder behind some of Old Town's larger custom homes — solid construction, generous lots.$lot$,$lot$<p>T.W. Lewis is the late-20th-century builder behind some of Old Town's larger custom homes. Solid construction, generous lots, and floor plans that have aged well make these a favorite for buyers who want space without leaving the neighborhood.</p><p>They tend to trade less often than the postwar stock, so knowing where they are — and what makes a good one — is half the battle.</p>$lot$,2,'published', now() - interval '8 minutes')
